BEGIN;

UPDATE accounts SET balance = balance - 100 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 100 WHERE account_id = 2;

-- A CHECK constraint such as balance >= 0 enforces consistency.
-- If the debit would make account 1 negative, the statement errors
-- and we roll back so no money is lost or created.

-- On success:
COMMIT;

-- On any error during the transaction, instead run:
-- ROLLBACK;

-- Session A and Session B both want to decrement inventory safely.

BEGIN;
-- Take a row lock so the read is consistent until commit
SELECT quantity FROM inventory WHERE product_id = 10 FOR UPDATE;
-- ... application checks quantity >= 1 ...
UPDATE inventory SET quantity = quantity - 1 WHERE product_id = 10;
COMMIT;

-- A concurrent session running the same block must wait for the
-- FOR UPDATE lock to release, then sees the committed value,
-- preventing two sessions from both reading the old quantity
-- and double-decrementing (a lost update).

-- Strongest: behaves as if transactions ran one at a time
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN;
SELECT SUM(amount) FROM ledger WHERE account_id = 5;
INSERT INTO ledger (account_id, amount) VALUES (5, -50);
COMMIT;

-- Common OLTP default: prevents dirty reads, allows non-repeatable reads
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
